//! Fictional ordinary discovery intake, final combined gate only.
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_search_scheduling_is_single_leased_and_respects_saved_source_confirmation_and_stop(){
    let(mut c,binding,_)=sync_fixture(json!([])).await;sqlx::query("UPDATE candidate_profiles SET preferences=jsonb_set(preferences,'{target_titles}','[\"Rust Engineer\"]'::jsonb)").execute(&mut c).await.unwrap();
    let work=automated_apply_agents::execution::search::work(&mut c,&binding).await.unwrap().unwrap();assert_eq!(work["operation"],"search_jobs");assert_eq!(work["policy_revision"],162);assert!(automated_apply_agents::execution::search::work(&mut c,&binding).await.unwrap().is_none());assert!(work["admitted_actions"].is_null());let mut config=browser_pref(&mut c,"application_queue_policy").await;config["state"]=json!("STOPPED");browser_save(&mut c,"application_queue_policy",config).await;assert!(automated_apply_agents::execution::search::work(&mut c,&binding).await.unwrap().is_none());
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_batch_intake_retains_permanent_uncertain_and_damaged_receipt_history_and_deduplicates_aliases(){
    let(mut c,_,_)=sync_fixture(json!([])).await;let prior=execution_enqueue(&mut c,"123456789012").await;let mut unknown=prior.clone();unknown["status"]=json!("unknown");unknown["stage"]=json!("SUBMISSION_UNKNOWN");unknown["admitted_actions"]=json!([{"fingerprint":"apply:spent"}]);let key=format!("apply_work:{}",prior["id"].as_str().unwrap());browser_save(&mut c,&key,unknown.clone()).await;browser_save(&mut c,"naukri_worker_receipt:223456789012",json!({"damaged":true})).await;
    let urls=["https://www.naukri.com/job-listings-new-slug-123456789012","https://www.naukri.com/job-listings-new-slug-223456789012","https://www.naukri.com/job-listings-fictional-323456789012","https://www.naukri.com/job-listings-another-slug-323456789012/","https://example.com/unrelated"].map(str::to_owned);assert_eq!(automated_apply_agents::execution::intake::batch(&mut c,&urls,"naukri_ui_search").await.unwrap(),1);assert_eq!(browser_pref(&mut c,&key).await,unknown);assert_eq!(automated_apply_agents::execution::intake::batch(&mut c,&urls,"naukri_ui_search").await.unwrap(),0);let values:Vec<Value>=sqlx::query_scalar("SELECT value FROM owner_preferences WHERE starts_with(key,'apply_work:') AND value->>'requisition'='323456789012'").fetch_all(&mut c).await.unwrap();assert_eq!(values.len(),1);assert_eq!(values[0]["admitted_actions"],json!([]));
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_batch_intake_respects_capacity_and_suppressed_batch_or_event_ack_rolls_back_all_rows(){
    let(mut c,_,_)=sync_fixture(json!([])).await;let urls=["123456789012","223456789012","323456789012"].map(|n|format!("https://www.naukri.com/job-listings-fictional-{n}"));let before=browser_snapshot(&mut c).await;
    for prefix in ["apply_work:","apply_event:"]{sqlx::raw_sql("CREATE FUNCTION fixture_batch_drop() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN IF starts_with(NEW.key,TG_ARGV[0]) THEN RETURN NULL; END IF; RETURN NEW; END $$").execute(&mut c).await.unwrap();sqlx::raw_sql(sqlx::AssertSqlSafe(format!("CREATE TRIGGER fixture_batch_drop BEFORE INSERT ON owner_preferences FOR EACH ROW EXECUTE FUNCTION fixture_batch_drop('{prefix}')"))).execute(&mut c).await.unwrap();assert_eq!(automated_apply_agents::execution::intake::batch(&mut c,&urls,"naukri_ui_search").await.unwrap_err(),Failure("execution_write_ack_failed"));assert_eq!(browser_snapshot(&mut c).await,before);sqlx::raw_sql("DROP TRIGGER fixture_batch_drop ON owner_preferences;DROP FUNCTION fixture_batch_drop()").execute(&mut c).await.unwrap();}
    let mut config=browser_pref(&mut c,"application_queue_policy").await;config["policy"]["max_pending"]=json!(1);browser_save(&mut c,"application_queue_policy",config).await;assert_eq!(automated_apply_agents::execution::intake::batch(&mut c,&urls,"naukri_ui_search").await.unwrap(),1);assert_eq!(automated_apply_agents::execution::intake::batch(&mut c,&urls,"naukri_ui_search").await.unwrap(),0);
}
#[tokio::test(flavor="current_thread")]
#[ignore="requires dedicated disposable PostgreSQL harness"]
async fn execution_batch_intake_matches_legacy_slug_history_across_applied_jobs_and_unknown_packets(){
    let(mut c,_,packet)=sync_fixture(json!([])).await;let job:Uuid=packet["job_id"].as_str().unwrap().parse().unwrap();sqlx::query("UPDATE jobs SET source_platform='naukri',job_url='https://www.naukri.com/job-listings-old-slug-123456789012/',status='applied' WHERE id=$1").bind(job).execute(&mut c).await.unwrap();let urls=["https://www.naukri.com/job-listings-other-slug-123456789012".to_owned()];assert_eq!(automated_apply_agents::execution::intake::batch(&mut c,&urls,"naukri_ui_search").await.unwrap(),0);let(mut c,work,_)=submission_fixture().await;sqlx::query("UPDATE jobs SET source_platform='naukri',job_url='https://www.naukri.com/job-listings-old-slug-123456789012/',status='discovered' WHERE id=$1").bind(work["job_id"].as_str().unwrap().parse::<Uuid>().unwrap()).execute(&mut c).await.unwrap();sqlx::query("UPDATE application_packets SET lifecycle_state='submission_unknown' WHERE id=$1").bind(work["packet_id"].as_str().unwrap().parse::<Uuid>().unwrap()).execute(&mut c).await.unwrap();assert_eq!(automated_apply_agents::execution::intake::batch(&mut c,&urls,"naukri_ui_search").await.unwrap(),0);
}
